def article(item,i):
    anchor,title,link,label,paras=item
    paragraphs=''.join(f'<p>{x}</p>' for x in paras)
    related='<div class="article-related"><strong>روابط مرتبطة:</strong> <a href="articles.html#moving">نقل الأثاث</a> · <a href="articles.html#maintenance">الصيانة</a> · <a href="articles.html#cleaning">التنظيف</a> · <a href="articles.html#gas">أفران الغاز</a> · <a href="articles.html#contact">التواصل</a></div>'
    return f'<article id="{anchor}" class="long-article"><span class="article-number">{i:02d}</span><div><p class="card-kicker">دليل شركة الخيال</p><h2>{title}</h2>{paragraphs}<a class="icon-link" href="{link}">انتقل إلى {label} ←</a>{related}</div></article>'

content=''.join(article(x,i) for i,x in enumerate(articles,1))
